INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Proyek Butuh Tampilan, Tapi Hanya Ada Serial Monitor$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Proyek Arduino Anda sudah jalan, tetapi hasilnya hanya bisa dilihat lewat Serial Monitor di laptop. Begitu dilepas dari komputer, proyek jadi 'buta' — tidak ada informasi yang ditampilkan. Display LCD 16x2 adalah solusi termurah dan paling populer: dua baris, 16 karakter per baris, cukup untuk suhu, jarak, status, atau menu sederhana.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Cara Kerja LCD 16x2$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$LCD 16x2 memakai kontroler HD44780. Versi I2C memiliki modul backpack (PCF8574) sehingga hanya butuh 4 kabel: VCC, GND, SDA, SCL — jauh lebih hemat pin dibanding mode paralel yang butuh 6 pin digital. Modul I2C biasanya beralamat 0x27 atau 0x3F; alamat ini penting saat menulis program dan bisa dicek dengan sketch I2C Scanner.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Alat dan Bahan yang Diperlukan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Board Arduino Uno/Nano$txt$, $txt$Modul LCD 16x2 dengan backpack I2C$txt$, $txt$Kabel jumper male-to-female (4 buah)$txt$, $txt$Kabel USB dan komputer dengan Arduino IDE$txt$, $txt$Library LiquidCrystal_I2C (install via Library Manager)$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah 1: Rangkai Kabel dan Install Library$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Hubungkan VCC ke 5V, GND ke GND, SDA ke A4, dan SCL ke A5 pada Arduino Uno/Nano. Jangan tertukar SDA dan SCL — jika tertukar, LCD tidak merespons sama sekali. Lalu buka Arduino IDE, pilih Sketch > Include Library > Manage Libraries, cari 'LiquidCrystal_I2C' dan install. Jika belum tahu alamat modul, jalankan sketch contoh I2C Scanner untuk menemukannya.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Langkah 2: Upload Program dan Atur Kontras$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Buat sketch baru: include library, inisialisasi objek dengan alamat dan ukuran (16,2), panggil lcd.init() dan lcd.backlight() di setup(), lalu lcd.setCursor(kolom,baris) dan lcd.print("teks") di loop(). Upload dan lihat hasilnya. Jika layar menyala tapi teks tidak terlihat (kotak-kotak samar), putar trimpot biru di belakang modul perlahan sampai teks jelas terbaca.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Risiko, Kesalahan Umum, dan Pemeriksaan Hasil$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Layar biru kosong berarti alamat I2C salah — jalankan I2C scanner. Kotak hitam di baris pertama berarti kontras terlalu tinggi — putar trimpot. Kabel longgar adalah penyebab nomor satu kegagalan; pastikan koneksi kencang dan jangan memberi tegangan lebih dari 5V ke modul. Berhasil jika backlight menyala dan teks dua baris tampil jelas. Tindak lanjut: tampilkan data sensor (misalnya DHT11) atau buat menu sederhana dengan tombol.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Tumis Kangkung Selalu Lembek dan Hitam$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Kangkung yang dimasak terlalu lama berubah menjadi lembek, berair, dan berwarna kehitaman — tidak menggugah selera. Padahal tumis kangkung yang enak itu hijau cerah, batangnya masih renyah, dan bumbunya meresap. Rahasianya ada pada tiga hal: api besar, waktu singkat, dan kangkung yang benar-benar kering sebelum masuk wajan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Kenapa Kangkung Harus Cepat$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Kangkung mengandung banyak air. Jika dimasak dengan api kecil terlalu lama, air keluar dan sayur menjadi layu berkuah. Api besar menguapkan air permukaan dengan cepat sehingga sayur matang dalam 2-3 menit sambil tetap hijau. Prinsip yang sama dipakai restoran: wajan panas, gerakan cepat.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Bahan untuk 3-4 Porsi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$2 ikat kangkung segar (pilih yang batangnya renyah)$txt$, $txt$5 siung bawang merah, iris tipis; 3 siung bawang putih, cincang$txt$, $txt$5 buah cabai merah keriting, iris serong (sesuai selera)$txt$, $txt$1 sdt terasi bakar (opsional)$txt$, $txt$1 sdm saus tiram; 1/2 sdt garam; 1/4 sdt gula pasir$txt$, $txt$3 sdm minyak goreng$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah 1: Siapkan Kangkung dengan Benar$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Petik kangkung, buang bagian batang tua yang keras. Cuci bersih 2-3 kali lalu tiriskan sampai benar-benar kering — bisa dikibas-kibaskan atau ditiriskan di wadah berlubang 10 menit. Kangkung yang basah akan menurunkan suhu wajan dan membuatnya berkuah.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Langkah 2: Tumis Bumbu Lalu Kangkung dengan Api Besar$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Panaskan minyak dengan api besar sampai benar-benar panas (keluar asap tipis). Tumis bawang merah, bawang putih, cabai, dan terasi 30-45 detik sampai harum. Masukkan kangkung sekaligus, aduk cepat 1,5-2 menit. Tambahkan saus tiram, garam, dan gula, aduk 30 detik lagi lalu angkat. Total waktu kangkung di wajan tidak lebih dari 3 menit.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Risiko, Kesalahan Umum, dan Variasi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Api kecil membuat kangkung berair dan lembek — selalu pakai api besar. Kangkung basah harus ditiriskan dulu. Bumbu gosong akan pahit, dan saus tiram sudah asin jadi cicipi dulu sebelum tambah garam. Sajikan segera selagi hijau dan renyah; jangan dipanaskan ulang. Variasi: tambah 1 sdm tauco untuk tumis kangkung tauco, atau buat versi tanpa cabai untuk anak.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Gas Tak Terlihat yang Melimpah di Sekitar Kita$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setiap tarikan napas, sekitar 1% udara yang Anda hirup adalah argon — gas yang tidak berwarna, tidak berbau, dan tidak bereaksi dengan apa pun. Argon adalah gas mulia paling melimpah di atmosfer Bumi. Meski 'malas bereaksi', argon justru sangat berguna bagi industri modern.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Sifat Dasar dan Asal Argon$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Argon (simbol Ar, nomor atom 18) memiliki kulit elektron terluar yang penuh — inilah alasan ia sangat stabil dan hampir tidak pernah membentuk senyawa kimia. Ia tidak mudah terbakar dan tidak beracun. Argon di atmosfer sebagian besar berasal dari peluruhan radioaktif kalium-40 di kerak Bumi selama miliaran tahun, dan diperoleh industri sebagai produk samping distilasi udara cair.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Peran dalam Pengelasan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Kegunaan terbesar argon adalah sebagai gas pelindung dalam pengelasan (TIG/MIG welding). Saat logam cair terpapar udara, oksigen membuat lasan keropos dan rapuh. Semburan argon menyelimuti area lasan dan mengusir udara, sehingga sambungan menjadi kuat dan bersih. Tanpa argon, pengelasan stainless steel dan aluminium berkualitas tinggi hampir mustahil.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Argon dalam Kehidupan Sehari-hari$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Lampu pijar dan neon: argon mengisi bola lampu agar filamen tidak cepat putus$txt$, $txt$Jendela kaca ganda: rongga diisi argon sebagai isolator panas yang lebih baik dari udara$txt$, $txt$Pengawetan dokumen bersejarah: arsip disimpan dalam atmosfer argon agar tidak teroksidasi$txt$, $txt$Industri semikonduktor: atmosfer argon melindungi silikon saat diproses$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Nama, Penemuan, dan Kesimpulan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Nama 'argon' berasal dari bahasa Yunani 'argos' yang berarti 'malas' — merujuk pada keengganannya bereaksi. Ia ditemukan pada 1894 oleh Lord Rayleigh dan William Ramsay, penemuan berhadiah Nobel. Argon membuktikan bahwa 'tidak melakukan apa-apa' bisa sangat berharga: dengan tetap inert, ia melindungi lasan, mengawetkan sejarah, dan memurnikan teknologi.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Irian Barat yang Belum Kembali$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Ketika kedaulatan Indonesia diakui pada 1949, satu wilayah belum kembali: Irian Barat (Papua). Belanda mempertahankannya dengan dalih perbedaan etnis dan kesiapan, bahkan merencanakan 'negara boneka' Papua. Hasil KMB menyisakan statusnya untuk dirundingkan kemudian, tetapi perundingan demi perundingan buntu. Kesabaran Jakarta habis pada akhir 1961.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Tri Komando Rakyat: 19 Desember 1961$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Pada 19 Desember 1961 di Yogyakarta, Presiden Soekarno mengumandangkan Tri Komando Rakyat (Trikora): pertama, gagalkan pembentukan 'negara boneka' Papua; kedua, kibarkan Sang Merah Putih di Irian Barat; ketiga, bersiap untuk mobilisasi umum mempertahankan kemerdekaan. Seruan ini menjadi dasar politik dan moral seluruh operasi pembebasan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Operasi Militer dan Pertempuran Laut Aru$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Operasi dirancang tiga tahap: infiltrasi (penyusupan sukarelawan), eksploitasi (perebutan wilayah bertahap), dan konsolidasi (penguasaan penuh). Pada 15 Januari 1962, tiga kapal torpedo Indonesia bentrok dengan kapal perang Belanda di Laut Aru; KRI Macan Tutul tenggelam dan Komodor Yos Sudarso gugur dengan pekik 'Kobarkan semangat pertempuran!' — diperingati sebagai Hari Dharma Samudera.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Perjanjian New York dan Penentuan Pendapat Rakyat$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Kekuatan militer Indonesia yang membesar membuat Belanda dan sekutunya khawatir konflik meluas, sehingga Amerika Serikat menekan Belanda untuk berunding. Perjanjian New York (15 Agustus 1962) menyerahkan Irian Barat ke PBB (UNTEA), lalu ke Indonesia pada 1 Mei 1963. Pada 1969 digelar Pepera yang menyatakan rakyat memilih bergabung dengan Indonesia, diterima PBB melalui Resolusi 2504.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Makna Trikora bagi Indonesia$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Trikora menunjukkan kombinasi diplomasi, tekanan militer yang kredibel, dan dukungan rakyat mampu mengubah kebuntuan internasional. Operasi ini juga menjadi tonggak profesionalisme TNI — dari pertempuran laut hingga operasi gabungan lintas matra. Irian Barat yang kembali melengkapi peta Indonesia seperti yang kita kenal hari ini.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah mempelajari bab ini, siswa diharapkan mampu: (1) mengelompokkan hidrokarbon berdasarkan jenis ikatannya; (2) memberi nama senyawa hidrokarbon menurut aturan IUPAC; (3) menentukan isomer suatu senyawa; (4) menuliskan reaksi pembakaran, adisi, substitusi, dan eliminasi; (5) menjelaskan kegunaan hidrokarbon dalam kehidupan sehari-hari.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Pengertian dan Jenis Hidrokarbon$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Hidrokarbon adalah senyawa organik yang hanya terdiri dari atom karbon (C) dan hidrogen (H). Berdasarkan ikatan antar atom karbonnya: alkana (ikatan tunggal, jenuh, paling stabil), alkena (ikatan rangkap dua), dan alkuna (ikatan rangkap tiga, lebih reaktif karena ikatan rangkapnya).$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Tata Nama IUPAC$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Langkah penamaan: (1) tentukan rantai induk terpanjang; (2) beri nomor dari ujung terdekat cabang/ikatan rangkap; (3) sebutkan cabang alkil dengan awalan di-, tri-; (4) gabungkan. Contoh: CH3-CH(CH3)-CH2-CH3 adalah 2-metilbutana. Untuk alkena/alkuna, akhiran menjadi -ena/-una dan nomor menunjukkan posisi ikatan rangkap, misalnya CH2=CH-CH2-CH3 adalah 1-butena.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Isomer dan Contoh Soal Terpecahkan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Isomer adalah senyawa berumus molekul sama tetapi struktur berbeda; C4H10 punya 2 isomer (n-butana dan 2-metilpropana), C6H14 punya 5. Contoh soal: nama IUPAC dari CH3-C(CH3)2-CH2-CH3 adalah 2,2-dimetilbutana — rantai terpanjang 4 karbon (butana) dengan dua cabang metil di karbon nomor 2.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Reaksi-reaksi Hidrokarbon$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Pembakaran sempurna: hidrokarbon + O2 menjadi CO2 + H2O (menghasilkan energi)$txt$, $txt$Substitusi (alkana): CH4 + Cl2 menjadi CH3Cl + HCl dengan bantuan cahaya UV$txt$, $txt$Adisi (alkena/alkuna): C2H4 + Br2 menjadi C2H4Br2 — air bromin yang memudar sebagai uji$txt$, $txt$Eliminasi: kebalikan adisi, misalnya dehidrasi alkohol menjadi alkena$txt$, $txt$Polimerisasi: banyak molekul alkena bergabung menjadi polimer seperti polietena$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Latihan Soal dan Kunci Jawaban$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Soal 1: Gambarkan 3 isomer struktur C5H12 dan beri nama. Soal 2: Nama IUPAC dari CH3-CH=CH-CH(CH3)-CH3. Soal 3: Mengapa alkena mengalami adisi sedangkan alkana tidak? Kunci: (1) n-pentana, 2-metilbutana, 2,2-dimetilpropana. (2) 4-metil-2-pentena. (3) Ikatan pi alkena lebih lemah dan mudah putus sehingga molekul lain dapat beradisi; alkana hanya punya ikatan sigma tunggal yang kuat dan jenuh. Kegunaan: bensin, LPG, plastik (polietena, PVC), dan asetilena untuk pengelasan.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah belajar bab ini, kamu diharapkan bisa: (1) menyebutkan contoh kenampakan alam daratan dan perairan; (2) menjelaskan perbedaan dataran rendah, dataran tinggi, dan pegunungan; (3) menyebutkan manfaat kenampakan alam bagi kehidupan manusia; (4) menunjukkan sikap menjaga kelestarian alam.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Apa Itu Kenampakan Alam?$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Kenampakan alam adalah segala sesuatu yang tampak di permukaan bumi dan terbentuk secara alami, bukan buatan manusia. Contohnya gunung, sungai, danau, laut, dan pantai. Kenampakan alam dibagi dua: kenampakan alam daratan (di atas permukaan tanah) dan kenampakan alam perairan (berupa air).$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Kenampakan Alam Daratan dan Perairan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Dataran rendah (0-200 m): cocok untuk sawah dan permukiman — contohnya pantai utara Jawa$txt$, $txt$Dataran tinggi (>200 m): sejuk, cocok untuk kebun teh — contohnya Dieng dan Lembang$txt$, $txt$Pegunungan dan gunung berapi: tanah subur — contohnya Merapi dan Bromo$txt$, $txt$Sungai: aliran air tawar — contohnya Musi, Bengawan Solo, Kapuas$txt$, $txt$Danau, laut, selat, teluk: contohnya Danau Toba, Laut Jawa, Selat Sunda, Teluk Jakarta$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Manfaat Kenampakan Alam$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Kenampakan alam sangat bermanfaat: dataran rendah untuk pertanian padi, dataran tinggi untuk perkebunan teh, gunung berapi membuat tanah subur, sungai untuk irigasi dan transportasi, danau dan laut untuk perikanan, serta pantai dan gunung untuk wisata. Karena itu kita wajib menjaga kelestarian alam: tidak membuang sampah ke sungai dan tidak merusak hutan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Ayo Mengamati!$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Coba amati lingkungan sekitarmu: apakah daerahmu termasuk dataran rendah atau dataran tinggi? Adakah sungai atau danau di dekat rumahmu? Catat hasilnya, lalu ceritakan manfaat kenampakan alam itu bagi warga sekitarmu. Kegiatan ini melatihmu menghubungkan pelajaran dengan kehidupan nyata.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Latihan Soal dan Kunci Jawaban$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Soal 1: Sebutkan 3 contoh kenampakan alam daratan dan 3 perairan! Soal 2: Mengapa dataran tinggi cocok untuk kebun teh? Soal 3: Sebutkan 2 cara menjaga kelestarian sungai! Kunci: (1) Daratan — dataran rendah, dataran tinggi, gunung; Perairan — sungai, danau, laut. (2) Udaranya sejuk dan tanahnya subur. (3) Tidak membuang sampah/limbah ke sungai; ikut kerja bakti membersihkan sungai.$txt$));
